<script setup>
import{computed,onMounted,ref}from'vue';import api from '../../../services/api';import FormErrors from '../../../components/ui/FormErrors.vue';import PlanCard from '../../../components/admin/plans/PlanCard.vue';
const plans=ref([]),loading=ref(true),error=ref(null);const stats=computed(()=>({total:plans.value.length,active:plans.value.filter(p=>p.status==='active').length,subscriptions:plans.value.reduce((n,p)=>n+(p.subscriptions_count||0),0),trials:plans.value.reduce((n,p)=>n+(p.trial_subscriptions_count||0),0)}));onMounted(async()=>{try{plans.value=(await api.get('/v1/platform/plans')).data.data}catch(e){error.value=e}finally{loading.value=false}})
</script>
<template><div><header class="page-header"><div><p class="eyebrow">Platform administration</p><h1>Subscription Plans</h1><p>Create and manage pricing plans, limits and features available to clinics.</p></div><RouterLink class="btn" :to="{name:'admin.plans.create'}">+ Add New Plan</RouterLink></header><FormErrors :error="error"/><p v-if="loading" class="loading-state">Loading plans...</p><template v-else><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><article class="summary-card"><p>Total Plans</p><strong>{{stats.total}}</strong></article><article class="summary-card"><p>Active Plans</p><strong>{{stats.active}}</strong></article><article class="summary-card"><p>Total Subscriptions</p><strong>{{stats.subscriptions}}</strong></article><article class="summary-card"><p>Trial Subscriptions</p><strong>{{stats.trials}}</strong></article></div><div class="mt-6 grid gap-5 md:grid-cols-2 xl:grid-cols-3"><PlanCard v-for="plan in plans" :key="plan.id" :plan="plan"/></div><p v-if="!plans.length" class="empty-state admin-card mt-6">No subscription plans have been created.</p></template></div></template>
